/* Shared production/sandbox VN presenter. Text remains DOM text, never authored HTML. */
(function(g){'use strict';const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
function render(root,state,p,rows,choose,{prefix='worldChoice-'}={}){const ev=p.event,novel=ev.novel,node=novel.nodes.find(n=>n.id===(p.nodeId||novel.startNode)),npc=rows.find(r=>r.kind==='npc'&&r.id===(node.npcId||novel.npcId)),stage=el('section','event-vn');stage.setAttribute('aria-label','บทสนทนา '+ev.name);const bg=node.background||novel.background;if(bg){const image=el('img','event-vn-background');image.src=bg;image.alt='';image.onerror=()=>image.remove();stage.append(image);}const picture=npc?.portrait||npc?.avatar;if(picture){const image=el('img','event-vn-portrait');image.src=picture;image.alt=npc.displayName||npc.name;image.onerror=()=>{image.remove();};stage.append(image);}const box=el('div','event-vn-dialogue');box.append(el('p','event-vn-speaker',npc?.displayName||npc?.name||'ผู้บรรยาย'),el('p','event-vn-text',node.text));const choices=el('div','event-vn-choices');for(const ch of node.choices){const button=el('button','',ch.label+(ch.goldDelta?' ('+(ch.goldDelta>0?'+':'')+ch.goldDelta+' เหรียญ)':''));button.id=prefix+ch.id;button.disabled=state.gold+ch.goldDelta<0;button.onclick=()=>choose(ch.id);choices.append(button);}box.append(choices);stage.append(box);root.append(stage);}
function journal(root,state){const book=state.eventJournal;if(!book||!book.quests.length&&!book.stories.length)return;const detail=el('details','event-journal'),summary=el('summary','', 'สมุดเควสและเรื่องราว ('+book.quests.length+' เควส)');detail.append(summary);for(const q of book.quests){const section=el('section');section.append(el('h3','',q.title+' · '+({active:'กำลังทำ',completed:'สำเร็จ',failed:'ล้มเหลว'}[q.status])),el('p','',q.description));detail.append(section);}if(book.stories.length){detail.append(el('h3','','บันทึกเรื่องราวล่าสุด'));for(const line of book.stories.slice(0,12))detail.append(el('p','',line.text));}root.append(detail);}
g.DecideEventNovelUI={render,journal};})(window);
